 * Who gets a digest: everyone who set at least one notification kind to
 * `digestOnly`, minus suspended members. Opting into the digest is what
 * suppresses the immediate emails, so the two lists are two views of the
 * same preference.
 */
export async function listDigestRecipients(
  orgId: OrgId,
): Promise<readonly UserId[]> {
  const subscribers = await preferenceRepo.listDigestSubscribers(orgId);
  const recipients: UserId[] = [];
  for (const userId of subscribers) {
    if (await memberRepo.isMemberSuspended(orgId, userId)) continue;
    recipients.push(userId);
  }
  return recipients;
}''')
