"use client";

/**
 * Assignee combobox restricted to active members.
 */
import { Combobox, type ComboboxOption } from "@/components/ui/combobox";
import { isLive } from "@/lib/soft-delete";
import type { UserId } from "@/types/common";
import type { MemberWithUser } from "@/types/member";
import type { ReactElement } from "react";

export type IssueAssigneePickerProps = {
  value: UserId | null;
  members: readonly MemberWithUser[];
  disabled?: boolean;
  onChange: (userId: UserId | null) => void;
};

/**
 * Only members who can actually act in the org are offered: an invited member
 * has not accepted yet and a suspended one must not receive new work. Removed
 * members are soft-deleted, so `isLive()` decides that part.
 */
export function assignableMembers(
  members: readonly MemberWithUser[],
): readonly MemberWithUser[] {
  return members.filter(
    (member) => member.status === "active" && isLive(member),
  );
}

export function IssueAssigneePicker(
  props: IssueAssigneePickerProps,
): ReactElement | null {
  const options: readonly ComboboxOption[] = assignableMembers(
    props.members,
  ).map((member) => ({
    value: member.userId,
    label: member.user.name,
    description: member.user.email,
  }));

  return (
    <Combobox
      value={props.value}
      options={options}
      placeholder={props.disabled === true ? "Assignee locked" : "Unassigned"}
      emptyLabel="No assignable members"
      onChange={(value) => props.onChange(value as UserId | null)}
    />
  );
}
"use client";

/**
 * Members settings table; role and remove controls are permission gated.
 *
 * Must call (do not reimplement): can
 */
import { Avatar } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeaderCell,
  TableRow,
} from "@/components/ui/table";
import { formatRelative } from "@/lib/date";
import { can } from "@/lib/permissions";
import { isLive } from "@/lib/soft-delete";
import type { MemberId } from "@/types/common";
import type { Actor, MemberWithUser, Role } from "@/types/member";
import type { ReactElement } from "react";
import { memberResource } from "../permission/resources";
import { RoleBadge } from "../permission/role-badge";
import { RoleSelect } from "./role-select";

export type MemberTableProps = {
  members: readonly MemberWithUser[];
  actor: Actor;
  onRoleChange: (memberId: MemberId, role: Role) => void;
  onRemove: (memberId: MemberId) => void;
};

export function MemberTable(props: MemberTableProps): ReactElement | null {
  const { members, actor, onRoleChange, onRemove } = props;
  const visible = members.filter(isLive);

  return (
    <Table caption="Organization members">
      <TableHead>
        <TableRow>
          <TableHeaderCell>Member</TableHeaderCell>
          <TableHeaderCell>Role</TableHeaderCell>
          <TableHeaderCell>Status</TableHeaderCell>
          <TableHeaderCell>Last seen</TableHeaderCell>
          <TableHeaderCell></TableHeaderCell>
        </TableRow>
      </TableHead>

      <TableBody>
        {visible.map((member) => {
          const resource = memberResource(member);
          const mayChangeRole = can(actor, "member:update_role", resource);
          // Nobody removes themselves from the members table; leaving the org
          // is a separate, deliberate flow.
          const isSelf = member.userId === actor.userId;
          const mayRemove = can(actor, "member:remove", resource) && !isSelf;

          return (
            <TableRow key={member.id}>
              <TableCell>
                <span className="flex items-center gap-2">
                  <Avatar
                    name={member.user.name}
                    src={member.user.avatarUrl}
                    size="sm"
                  />
                  <span>
                    <span className="block font-medium">
                      {member.user.name}
                    </span>
                    <span className="block text-xs text-neutral-500">
                      {member.user.email}
                    </span>
                  </span>
                </span>
              </TableCell>

              <TableCell className="w-44">
                {mayChangeRole ? (
                  <RoleSelect
                    value={member.role}
                    actor={actor}
                    onChange={(role) => onRoleChange(member.id, role)}
                  />
                ) : (
                  <RoleBadge role={member.role} />
                )}
              </TableCell>

              <TableCell className="w-32">
                <Badge
                  tone={member.status === "active" ? "success" : "warning"}
                  size="sm"
                >
                  {member.status}
                </Badge>
              </TableCell>

              <TableCell className="w-36 text-sm text-neutral-500">
                {member.lastSeenAt === null
                  ? "Never"
                  : formatRelative(member.lastSeenAt)}
              </TableCell>

              <TableCell className="w-28 text-right">
                {mayRemove ? (
                  <Button
                    variant="danger"
                    size="sm"
                    onClick={() => onRemove(member.id)}
                  >
                    Remove
                  </Button>
                ) : null}
              </TableCell>
            </TableRow>
          );
        })}
      </TableBody>
    </Table>
  );
}
