import { subscribe } from "@/lib/event-bus";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as ms from "@/server/services/member-service";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import { notify } from "@/server/services/notification-service";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as activityRepo from "@/server/repositories/activity-repository";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("suspend", () => {
  it("works end to end", async () => {
    const off = registerActivityListeners();
    const t = await createTenant("susp", "growth");
    const target = (await memberRepo.findMember(t.org.id, t.userIds.member))!;
    const ownerM = (await memberRepo.findMember(t.org.id, t.userIds.owner))!;
    const events: unknown[] = [];
    const off2 = subscribe("member.suspended", (p) => { events.push(p); });
    const seatsBefore = await memberRepo.countActiveMembers(t.org.id);
    await expect(ms.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: ownerM.id })).rejects.toThrow();
    await expect(ms.suspendMember(t.actors.owner, { orgId: t.org.id, memberId: ownerM.id })).rejects.toThrow();
    const s = await ms.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: target.id });
    expect(s.status).toBe("suspended");
    const again = await ms.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: target.id });
    expect(again.status).toBe("suspended");
    expect(events.length).toBe(1);
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(seatsBefore);
    expect((await usageRepo.recomputeUsage(t.org.id)).seatsUsed).toBe(seatsBefore);
    expect(await ms.resolveActor(t.userIds.member, t.org.id)).toBeNull();
    expect((await orgRepo.listOrgsForUser(t.userIds.member)).length).toBe(0);
    await expect(issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.member }))).rejects.toBeInstanceOf(ms.MemberSuspendedError);
    const issue = await issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id));
    await expect(issueService.assignIssue(t.actors.owner, { orgId: t.org.id, issueId: issue.id, assigneeId: t.userIds.member })).rejects.toBeInstanceOf(ms.MemberSuspendedError);
    expect(await notify(t.org.id, "member_joined", [t.userIds.member], { title: "x", body: "y", href: "/", actorId: null })).toEqual([]);
    const c = await commentService.createComment(t.actors.owner, { orgId: t.org.id, issueId: issue.id, body: "hi @member", parentId: null, mentionedUserIds: [t.userIds.member] } as never);
    expect(c.mentionedUserIds).toEqual([]);
    const r = await ms.reinstateMember(t.actors.admin, { orgId: t.org.id, memberId: target.id });
    expect(r.status).toBe("active");
    const c2 = await commentService.createComment(t.actors.owner, { orgId: t.org.id, issueId: issue.id, body: "hi @member", parentId: null, mentionedUserIds: [] } as never);
    expect(c2.mentionedUserIds).toEqual([t.userIds.member]);
    await new Promise((res) => setTimeout(res, 50));
    const log = await activityRepo.listActivity({ orgId: t.org.id, action: ["member.suspended", "member.reinstated"], limit: 10, cursor: null } as never);
    expect(log.items.map((e) => e.action).sort()).toEqual(["member.reinstated", "member.suspended"]);
    const viewer = (await memberRepo.findMember(t.org.id, t.userIds.viewer))!;
    await ms.removeMember(t.actors.owner, { orgId: t.org.id, memberId: viewer.id });
    await expect(ms.suspendMember(t.actors.owner, { orgId: t.org.id, memberId: viewer.id })).rejects.toBeInstanceOf(NotFoundError);
    off(); off2();
  });
});
